<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Desktop Environment</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: Ubuntu, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
            overflow: hidden;
        }

        #desktop {
            width: 100vw;
            height: 100vh;
            display: flex;
            flex-direction: column;
            background: linear-gradient(135deg, #2a2a2a 0%, #1a1a1a 100%);
        }

        #taskbar {
            background: #2d2d2d;
            border-bottom: 1px solid #3a3a3a;
            padding: 10px;
            display: flex;
            gap: 10px;
            height: 50px;
            align-items: center;
            flex-shrink: 0;
        }

        #taskbar button {
            background: #3d3d3d;
            color: #fff;
            border: none;
            padding: 8px 15px;
            border-radius: 4px;
            cursor: pointer;
            font-size: 14px;
            transition: background 0.2s;
        }

        #taskbar button:hover {
            background: #4d4d4d;
        }

        #desktop > div:not(#taskbar) {
            flex: 1;
            position: relative;
        }

        .window {
            position: absolute;
            background: #2d2d2d;
            border: 1px solid #3a3a3a;
            border-radius: 8px;
            display: none;
            flex-direction: column;
            width: 500px;
            height: 400px;
            min-width: 360px;
            min-height: 240px;
            box-shadow: 0 10px 40px rgba(0, 0, 0, 0.5);
            z-index: 100;
        }

        .window.open {
            display: flex;
        }

        .window-titlebar {
            background: #1a1a1a;
            border-bottom: 1px solid #3a3a3a;
            padding: 10px 15px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            cursor: move;
            border-radius: 8px 8px 0 0;
            user-select: none;
            flex-shrink: 0;
        }

        .window-title {
            color: #fff;
            font-weight: 500;
            font-size: 14px;
        }

        .win-close {
            background: #d74545;
            color: #fff;
            border: none;
            width: 32px;
            height: 32px;
            border-radius: 4px;
            cursor: pointer;
            font-size: 18px;
            display: flex;
            align-items: center;
            justify-content: center;
            transition: background 0.2s;
            flex-shrink: 0;
        }

        .win-close:hover {
            background: #e74c3c;
        }

        .window-content {
            flex: 1;
            overflow: auto;
            padding: 0;
            color: #fff;
            display: flex;
            flex-direction: column;
        }

        /* Files app */
        #files-path {
            background: #1a1a1a;
            padding: 10px 15px;
            font-family: monospace;
            font-size: 13px;
            color: #4a9eff;
            border-bottom: 1px solid #3a3a3a;
            flex-shrink: 0;
        }

        .files-nav {
            display: flex;
            gap: 5px;
            padding: 5px 15px;
            background: #1a1a1a;
            border-bottom: 1px solid #3a3a3a;
            flex-shrink: 0;
        }

        #files-up {
            background: #3d3d3d;
            color: #fff;
            border: none;
            padding: 5px 10px;
            border-radius: 4px;
            cursor: pointer;
            font-size: 12px;
        }

        #files-up:hover {
            background: #4d4d4d;
        }

        #files-up:disabled {
            opacity: 0.5;
            cursor: not-allowed;
        }

        .files-list {
            display: flex;
            flex-direction: column;
            gap: 1px;
            flex: 1;
            overflow: auto;
        }

        .fs-item {
            padding: 10px 15px;
            background: #2d2d2d;
            color: #fff;
            cursor: default;
            transition: background 0.2s;
            user-select: none;
            flex-shrink: 0;
        }

        .fs-item:hover {
            background: #3d3d3d;
        }

        .fs-item.folder::before {
            content: '📁 ';
        }

        .fs-item.file::before {
            content: '📄 ';
        }

        /* Notepad app */
        #tabs {
            display: flex;
            gap: 2px;
            background: #1a1a1a;
            padding: 10px 5px;
            border-bottom: 1px solid #3a3a3a;
            align-items: center;
            flex-shrink: 0;
            overflow-x: auto;
        }

        .tab {
            background: #3d3d3d;
            color: #fff;
            border: 1px solid #4d4d4d;
            padding: 6px 12px;
            border-radius: 4px 4px 0 0;
            cursor: pointer;
            font-size: 12px;
            transition: background 0.2s;
            max-width: 150px;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
            flex-shrink: 0;
        }

        .tab:hover {
            background: #4d4d4d;
        }

        .tab.active {
            background: #2d2d2d;
            border-bottom-color: #2d2d2d;
        }

        #new-tab {
            background: #3d3d3d;
            color: #fff;
            border: none;
            padding: 6px 10px;
            border-radius: 4px;
            cursor: pointer;
            font-size: 12px;
            height: 28px;
            width: 28px;
            display: flex;
            align-items: center;
            justify-content: center;
            flex-shrink: 0;
        }

        #new-tab:hover {
            background: #4d4d4d;
        }

        #editor {
            flex: 1;
            background: #2d2d2d;
            color: #fff;
            border: none;
            padding: 15px;
            font-family: 'Courier New', monospace;
            font-size: 13px;
            resize: none;
        }

        #editor:focus {
            outline: none;
        }
    </style>
</head>
<body>
    <div id="desktop">
        <div id="taskbar">
            <button id="open-files">Files</button>
            <button id="open-notepad">Notepad</button>
        </div>

        <div style="flex: 1; position: relative;">
            <!-- Files Window -->
            <div id="files-window" class="window">
                <div class="window-titlebar">
                    <span class="window-title">Files</span>
                    <button class="win-close">✕</button>
                </div>
                <div id="files-path">/</div>
                <div class="files-nav">
                    <button id="files-up">← Up</button>
                </div>
                <div class="window-content">
                    <div class="files-list" id="files-list"></div>
                </div>
            </div>

            <!-- Notepad Window -->
            <div id="notepad-window" class="window">
                <div class="window-titlebar">
                    <span class="window-title">Notepad</span>
                    <button class="win-close">✕</button>
                </div>
                <div id="tabs"></div>
                <textarea id="editor" placeholder="Start typing..."></textarea>
            </div>
        </div>
    </div>

    <script>
        // ===== Filesystem Data =====
        const filesystem = {
            bin: { type: 'folder', children: {} },
            etc: { type: 'folder', children: {} },
            home: {
                type: 'folder',
                children: {
                    user: {
                        type: 'folder',
                        children: {
                            Documents: { type: 'folder', children: {} },
                            Downloads: { type: 'folder', children: {} },
                            Pictures: { type: 'folder', children: {} },
                            'README.txt': { type: 'file' },
                        }
                    }
                }
            },
            usr: { type: 'folder', children: {} },
            var: { type: 'folder', children: {} },
        };

        let currentPath = '/';

        function getNodeAtPath(path) {
            if (path === '/') return filesystem;
            const parts = path.split('/').filter(p => p);
            let node = filesystem;
            for (const part of parts) {
                node = node.children[part];
                if (!node) return null;
            }
            return node;
        }

        function renderFilesList() {
            const node = getNodeAtPath(currentPath);
            if (!node) return;

            const list = document.getElementById('files-list');
            list.innerHTML = '';

            const items = Object.entries(node.children || {}).sort((a, b) => {
                if (a[1].type !== b[1].type) {
                    return a[1].type === 'folder' ? -1 : 1;
                }
                return a[0].localeCompare(b[0]);
            });

            items.forEach(([name, item]) => {
                const el = document.createElement('div');
                el.className = `fs-item ${item.type}`;
                el.textContent = name;

                if (item.type === 'folder') {
                    el.addEventListener('dblclick', () => {
                        currentPath = currentPath === '/' ? `/${name}` : `${currentPath}/${name}`;
                        updateFilesPath();
                        renderFilesList();
                    });
                }

                list.appendChild(el);
            });

            document.getElementById('files-up').disabled = currentPath === '/';
        }

        function updateFilesPath() {
            document.getElementById('files-path').textContent = currentPath;
        }

        document.getElementById('files-up').addEventListener('click', () => {
            if (currentPath !== '/') {
                currentPath = currentPath.substring(0, currentPath.lastIndexOf('/')) || '/';
                updateFilesPath();
                renderFilesList();
            }
        });

        // ===== Notepad =====
        const notepadData = JSON.parse(localStorage.getItem('notepad')) || {
            tabs: [{ id: 1, title: 'Tab 1', content: '' }],
            activeTabId: 1
        };

        function saveNotepadData() {
            localStorage.setItem('notepad', JSON.stringify(notepadData));
        }

        function renderTabs() {
            const tabsContainer = document.getElementById('tabs');
            tabsContainer.innerHTML = '';

            notepadData.tabs.forEach(tab => {
                const tabEl = document.createElement('div');
                tabEl.className = `tab ${tab.id === notepadData.activeTabId ? 'active' : ''}`;
                tabEl.textContent = tab.title || 'Untitled';
                tabEl.addEventListener('click', () => {
                    notepadData.activeTabId = tab.id;
                    saveNotepadData();
                    renderTabs();
                    updateEditor();
                });
                tabsContainer.appendChild(tabEl);
            });

            const newTabBtn = document.createElement('button');
            newTabBtn.id = 'new-tab';
            newTabBtn.textContent = '+';
            newTabBtn.addEventListener('click', () => {
                const newId = Math.max(...notepadData.tabs.map(t => t.id), 0) + 1;
                const newTab = { id: newId, title: `Tab ${notepadData.tabs.length + 1}`, content: '' };
                notepadData.tabs.push(newTab);
                notepadData.activeTabId = newId;
                saveNotepadData();
                renderTabs();
                updateEditor();
            });
            tabsContainer.appendChild(newTabBtn);
        }

        function updateEditor() {
            const activeTab = notepadData.tabs.find(t => t.id === notepadData.activeTabId);
            const editor = document.getElementById('editor');
            editor.value = activeTab ? activeTab.content : '';
        }

        document.getElementById('editor').addEventListener('input', (e) => {
            const activeTab = notepadData.tabs.find(t => t.id === notepadData.activeTabId);
            if (activeTab) {
                activeTab.content = e.target.value;
                saveNotepadData();
            }
        });

        // ===== Window Management =====
        function openWindow(windowId) {
            const win = document.getElementById(windowId);
            win.classList.add('open');
            if (!win.style.left) {
                win.style.left = (Math.random() * 200 + 50) + 'px';
                win.style.top = (Math.random() * 100 + 50) + 'px';
            }
        }

        function closeWindow(windowId) {
            const win = document.getElementById(windowId);
            win.classList.remove('open');
        }

        document.getElementById('open-files').addEventListener('click', () => {
            openWindow('files-window');
        });

        document.getElementById('open-notepad').addEventListener('click', () => {
            openWindow('notepad-window');
        });

        document.querySelectorAll('.win-close').forEach(btn => {
            btn.addEventListener('click', (e) => {
                const win = e.target.closest('.window');
                closeWindow(win.id);
            });
        });

        // ===== Window Dragging =====
        let draggedWindow = null;
        let dragOffset = { x: 0, y: 0 };

        document.querySelectorAll('.window-titlebar').forEach(titlebar => {
            titlebar.addEventListener('mousedown', (e) => {
                if (e.target.closest('.win-close')) return;
                draggedWindow = e.target.closest('.window');
                const rect = draggedWindow.getBoundingClientRect();
                dragOffset.x = e.clientX - rect.left;
                dragOffset.y = e.clientY - rect.top;
                draggedWindow.style.zIndex = 1000;
            });
        });

        document.addEventListener('mousemove', (e) => {
            if (draggedWindow) {
                draggedWindow.style.left = (e.clientX - dragOffset.x) + 'px';
                draggedWindow.style.top = (e.clientY - dragOffset.y) + 'px';
            }
        });

        document.addEventListener('mouseup', () => {
            draggedWindow = null;
        });

        // ===== Initialize =====
        renderFilesList();
        renderTabs();
        updateEditor();
    </script>
</body>
</html>
